#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""真实案件25个（case-093 ~ case-117）"""
import json, os
from datetime import datetime
TODAY = datetime.now().strftime("%Y-%m-%d")
CASES_DIR = r"E:\Work\AIProjects\fun_detective\cases"

def diff(a,b,c,d): return {"线索密度":a,"误导数量":b,"诡计隐蔽度":c,"综合":d}
def clue(i,ct,tp,cl,tm): return {"线索编号":i,"线索内容":ct,"线索类型":tp,"指向结论":cl,"出现时机":tm}
def ch(n,i,r,m,a): return {"姓名":n,"身份":i,"与案件关系":r,"动机":m,"关键行为":a}

def save(case):
    st=case["基本信息"]["来源类型"]; rg=case["基本信息"]["地区"]; nm=case["基本信息"]["案件名称"]
    safe="".join(c for c in nm if c not in '<>:"/\\|?*')
    dp=os.path.join(CASES_DIR,st,rg); os.makedirs(dp,exist_ok=True)
    with open(os.path.join(dp,f"{safe}.json"),"w",encoding="utf-8") as f: json.dump(case,f,ensure_ascii=False,indent=2)
    print(f"  {case['id']}: {nm}")

def mk(cid,name,work,author,region,era,status,summary,full,rel,tl,end,chars,trick,ttypes,mech,igap,rediff,d,clues):
    return {"id":cid,"基本信息":{"案件名称":name,"来源类型":"真实案件","来源作品/事件":work,"作者/创作者":author,
        "地区":region,"年代":era,"案件状态":status,"一句话简介":summary,"参考链接":[]},
        "故事视图":{"故事摘要":summary,"完整故事":full,"人物关系":rel,"关键时间线":tl,"结局/真相":end,"角色档案":chars},
        "设计视图":{"核心诡计简述":trick,"诡计类型":ttypes,"可复用机制":mech,"信息差分析":igap,"红鲱鱼/误导":rediff,"难度评分":d,"线索链":clues},
        "游戏设计":{},"元数据":{"录入状态":"故事完成","录入日期":TODAY,"最后更新":TODAY,"飞书记录ID":"","版本":1}}

cases=[]

